<style>
    html {
        -webkit-text-size-adjust: 100%
    }

    @media (width<=720px) {
        .main-content {
            margin-top: 4rem
        }
    }

    @media (width<=720px) {
        .h2 {
            line-height: 1.5rem;
            font-size: 1.25rem
        }
