<style>
    * {
        box-sizing: border-box;
        margin: 0;
        padding: 0
    }

    html {
        line-height: 1.15;
        -webkit-text-size-adjust: 100%;
        color: #313131;
        font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"
    }

    body {
        display: flex;
        flex-direction: column;
        min-height: 100vh;
        margin: 0;
        padding: 0;
    }

    a {
        transition: color 150ms ease;
        background-color: rgba(0, 0, 0, 0);
        text-decoration: none;
        color: #0051c3
    }

    a:hover {
        text-decoration: underline;
        color: #ee730a
    }

    .main-content {
        margin: 8rem auto;
        padding-right: 1.5rem;
        padding-left: 1.5rem;
        width: 100%;
        max-width: 60rem
    }

    .main-content .loading-verifying {
        height: 76.391px
    }

    .spacer {
        margin: 2rem 0
    }

    .spacer-top {
        margin-top: 4rem
    }

    .spacer-bottom {
        margin-bottom: 2rem
    }

    @media (width<=720px) {
        .main-content {
            margin-top: 4rem
        }
    }

    .main-wrapper {
        display: flex;
        flex: 1;
        flex-direction: column;
        align-items: center;
        min-height: 0
    }

    .h1 {
        line-height: 3.75rem;
        font-size: 2.5rem;
        font-weight: 500
    }

    .h2 {
        line-height: 2.25rem;
        font-size: 1.5rem;
        font-weight: 500
    }

    .core-msg {
        line-height: 2.25rem;
        font-size: 1.5rem;
        font-weight: 400
    }

    @media (width<=720px) {
        .h1 {
            line-height: 1.75rem;
            font-size: 1.5rem
        }

        .h2 {
            line-height: 1.5rem;
            font-size: 1.25rem
        }

        .core-msg {
            line-height: 1.5rem;
            font-size: 1rem
        }
    }

    .text-center {
        text-align: center
    }

    .footer {
        margin: 0 auto;
        padding-right: 1.5rem;
        padding-left: 1.5rem;
        width: 100%;
        max-width: 60rem;
        line-height: 1.125rem;
        font-size: .75rem;
        margin-top: auto
    }

    .footer-inner {
        border-top: 1px solid #d9d9d9;
        padding-top: 1rem;
        padding-bottom: 1rem
    }

    .clearfix::after {
        display: table;
        clear: both;
        content: ""
    }

    .diagnostic-wrapper {
        margin-bottom: .5rem
    }

    .footer .ray-id {
        text-align: center
    }

    .footer .ray-id code {
        font-family: monaco, courier, monospace
    }

    .core-msg,
    .zone-name-title {
        overflow-wrap: break-word
    }

    @media (width<=720px) {
        .diagnostic-wrapper {
            display: block;
            text-align: center;
        }

        .clearfix::after {
            display: table;
            clear: both;
            content: ""
        }

        .zone-name-title {
            margin-bottom: 1rem
        }
    }

    .lds-ring {
        display: inline-block;
        position: relative;
        width: 1.875rem;
        height: 1.875rem
    }

    .lds-ring div {
        box-sizing: border-box;
        display: block;
        position: absolute;
        border: .3rem solid #595959;
        border-radius: 50%;
        border-color: #313131 rgba(0, 0, 0, 0) rgba(0, 0, 0, 0);
        width: 1.875rem;
        height: 1.875rem;
        animation: lds-ring 1.2s cubic-bezier(.5, 0, .5, 1) infinite
    }

    .lds-ring div:nth-child(1) {
        animation-delay: -.45s
    }

    .lds-ring div:nth-child(2) {
        animation-delay: -.3s
    }

    .lds-ring div:nth-child(3) {
        animation-delay: -.15s
    }

    @keyframes lds-ring {
        0% {
            transform: rotate(0deg)
        }

        100% {
            transform: rotate(360deg)
        }
    }

    @media (prefers-color-scheme:dark) {
        body {
            background-color: #222;
            color: #d9d9d9
        }

        body a {
            color: #fff
        }

        body a:hover {
            text-decoration: underline;
            color: #ee730a
        }

        body .lds-ring div {
            border-color: #999 rgba(0, 0, 0, 0) rgba(0, 0, 0, 0)
        }
    }

    #challenge-success-text {
        background-image: url(data:image/svg+xml;base64,);
        background-repeat: no-repeat;
        background-size: contain;
        padding-left: 42px
    }
</style>
